    21→void UWaitingRoomHUDWidget::NativeConstruct()
    22→{
    23→	Super::NativeConstruct();
    24→
    25→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget: NativeConstruct START ==="));
    26→
    27→	// 버튼 이벤트 바인딩
    28→	if (ReadyButton)
    29→	{
    30→		ReadyButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnReadyClicked);
    31→	}
    32→
    33→	if (StartGameButton)
    34→	{
    35→		StartGameButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnStartGameClicked);
    36→	}
    37→
    38→	if (LeaveButton)
    39→	{
    40→		LeaveButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnLeaveClicked);
    41→	}
    42→
    43→	if (ApplySettingsButton)
    44→	{
    45→		ApplySettingsButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnApplySettingsClicked);
    46→	}
    47→
    48→	if (GameModeComboBox)
    49→	{
    50→		GameModeComboBox->OnSelectionChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnGameModeSelectionChanged);
    51→	}
    52→
    53→	// GameState 가져오기 및 이벤트 바인딩
    54→	CachedGameState = GetWorld()->GetGameState<AWjWorldGameStateWaitingRoom>();
    55→	if (CachedGameState)
    56→	{
    57→		// ⭐ 디버깅: GameState 정보 로그
    58→		int32 PlayerCount = CachedGameState->GetPlayerCount();
    59→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: GameState found! PlayerCount = %d"), PlayerCount);
    60→		
    61→		// PlayerArray 내용 확인
    62→		for (int32 i = 0; i < CachedGameState->PlayerArray.Num(); i++)
    63→		{
    64→			APlayerState* PS = CachedGameState->PlayerArray[i];
    65→			if (PS)
    66→			{
    67→				UE_LOG(LogWjWorld, Warning, TEXT("  - PlayerState[%d]: %s (ID: %d)"), 
    68→					i, *PS->GetPlayerName(), PS->GetPlayerId());
    69→			}
    70→		}
    71→
    72→		// 델리게이트 바인딩
    73→		CachedGameState->OnRoomInfoChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnRoomInfoChanged);
    74→		CachedGameState->OnPlayerListChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnPlayerListChanged);
    75→
    76→		// 초기 데이터 로드
    77→		UpdateRoomInfo();
    78→		UpdatePlayerList();
    79→		UpdateStartGameButton();
    80→		UpdateReadyButton();
    81→
    82→		// 호스트 설정 패널 초기화
    83→		InitializeHostSettingsPanel();
    84→		UpdateHostSettingsPanelVisibility();
    85→
    86→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameState events bound"));
    87→	}
    88→	else
    89→	{
    90→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to get GameStateWaitingRoom"));
    91→	}
    92→
    93→	// PlayerState 이벤트 바인딩
    94→	APlayerController* PC = GetOwningPlayer();
    95→	if (PC)
    96→	{
    97→		AWjWorldPlayerStateBase* PlayerState = PC->GetPlayerState<AWjWorldPlayerStateBase>();
    98→		if (PlayerState)
    99→		{
   100→			PlayerState->OnReadyStateChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnPlayerReadyStateChanged);
   101→			UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerState events bound - %s"), *PlayerState->GetPlayerName());
   102→		}
   103→		else
   104→		{
   105→			UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: PlayerState is NULL"));
   106→		}
   107→	}
   108→
   109→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget: NativeConstruct END ==="));
   110→}
   111→
   112→void UWaitingRoomHUDWidget::NativeDestruct()
   113→{
   114→	// 델리게이트 언바인딩
   115→	if (CachedGameState)
   116→	{
   117→		CachedGameState->OnRoomInfoChanged.RemoveDynamic(this, &UWaitingRoomHUDWidget::OnRoomInfoChanged);
   118→		CachedGameState->OnPlayerListChanged.RemoveDynamic(this, &UWaitingRoomHUDWidget::OnPlayerListChanged);
   119→	}
   120→
   121→	if (GameModeComboBox)
   122→	{
   123→		GameModeComboBox->OnSelectionChanged.RemoveDynamic(this, &UWaitingRoomHUDWidget::OnGameModeSelectionChanged);
   124→	}
   125→
   126→	APlayerController* PC = GetOwningPlayer();
   127→	if (PC)
   128→	{
   129→		AWjWorldPlayerStateBase* PlayerState = PC->GetPlayerState<AWjWorldPlayerStateBase>();
   130→		if (PlayerState)
   131→		{
   132→			PlayerState->OnReadyStateChanged.RemoveDynamic(this, &UWaitingRoomHUDWidget::OnPlayerReadyStateChanged);
   133→		}
   134→	}
   135→
   136→	Super::NativeDestruct();
   137→}
   138→
   139→void UWaitingRoomHUDWidget::OnReadyClicked()
   140→{
   141→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Ready button clicked"));
   142→
   143→	// PlayerState의 준비 상태 토글
   144→	APlayerController* PC = GetOwningPlayer();
   145→	if (PC)
   146→	{
   147→		AWjWorldPlayerStateBase* PlayerState = PC->GetPlayerState<AWjWorldPlayerStateBase>();
   148→		if (PlayerState)
   149→		{
   150→			PlayerState->ToggleReady();
   151→		}
   152→		else
   153→		{
   154→			UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to get PlayerState"));
   155→		}
   156→	}
   157→}
   158→
   159→void UWaitingRoomHUDWidget::OnStartGameClicked()
   160→{
   161→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Start Game button clicked"));
   162→
   163→	// ⭐ 게임 시작 전에 현재 UI 설정을 자동으로 적용 (Apply Settings 버튼을 안 눌러도 반영되도록)
   164→	ApplyCurrentUISettings();
   165→
   166→	// GameMode의 StartGame 호출
   167→	AWjWorldGameModeWaitingRoom* GameMode = Cast<AWjWorldGameModeWaitingRoom>(GetWorld()->GetAuthGameMode());
   168→	if (GameMode)
   169→	{
   170→		GameMode->StartGame();
   171→	}
   172→	else
   173→	{
   174→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to get WjWorldGameModeWaitingRoom"));
   175→	}
   176→}
   177→
   178→void UWaitingRoomHUDWidget::OnLeaveClicked()
   179→{
   180→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Leave button clicked"));
   181→
   182→	// GameInstance를 통해 방 나가기
   183→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   184→	if (GameInstance)
   185→	{
   186→		bool bSuccess = GameInstance->LeaveRoom();
   187→		if (bSuccess)
   188→		{
   189→			UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Leaving room..."));
   190→
   191→			// 로비로 이동
   192→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   193→			UGameplayStatics::OpenLevel(GetWorld(), FName(*Settings->GetLobbyMapPath()));
   194→		}
   195→		else
   196→		{
   197→			UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to leave room"));
   198→		}
   199→	}
   200→	else
   201→	{
   202→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: GameInstance is null"));
   203→	}
   204→}
   205→
   206→void UWaitingRoomHUDWidget::OnRoomInfoChanged(const FRoomSettings& RoomSettings)
   207→{
   208→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Room info changed event received - GameMode: %s, Map: %s"),
   209→		*RoomSettings.GameMode, *RoomSettings.MapName);
   210→
   211→	// ⭐ 직접 전달받은 설정으로 UI 업데이트 (타이밍 이슈 방지)
   212→	UpdateRoomInfo(&RoomSettings);
   213→
   214→	// 호스트 설정 패널의 ComboBox 선택도 업데이트 (초기화 타이밍 이슈 해결)
   215→	if (GameModeComboBox && !RoomSettings.GameMode.IsEmpty())
   216→	{
   217→		GameModeComboBox->SetSelectedOption(RoomSettings.GameMode);
   218→		UpdateMapComboBoxForGameMode(RoomSettings.GameMode);
   219→
   220→		// 맵 선택도 업데이트
   221→		if (MapComboBox && !RoomSettings.MapName.IsEmpty())
   222→		{
   223→			for (const auto& Pair : MapOptionDisplayToValue)
   224→			{
   225→				if (Pair.Value == RoomSettings.MapName)
   226→				{
   227→					MapComboBox->SetSelectedOption(Pair.Key);
   228→					break;
   229→				}
   230→			}
   231→		}
   232→	}
   233→}
   234→
   235→void UWaitingRoomHUDWidget::OnPlayerListChanged(const TArray<FPlayerDisplayInfo>& PlayerList)
   236→{
   237→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Player list changed event received - %d players"), PlayerList.Num());
   238→	
   239→	// ⭐ 플레이어 목록 업데이트
   240→	UpdatePlayerList();
   241→	
   242→	// ⭐ 플레이어 수도 함께 업데이트 (중요!)
   243→	UpdateRoomInfo();
   244→	
   245→	// 게임 시작 버튼 상태 업데이트
   246→	UpdateStartGameButton();
   247→}
   248→
   249→void UWaitingRoomHUDWidget::OnPlayerReadyStateChanged(int32 PlayerID, bool bIsReady)
   250→{
   251→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Player %d ready state changed to %d"), PlayerID, bIsReady);
   252→	UpdateReadyButton();
   253→	UpdatePlayerList();
   254→	UpdateStartGameButton();
   255→}
   256→
   257→void UWaitingRoomHUDWidget::UpdateRoomInfo(const FRoomSettings* InSettings)
   258→{
   259→	// 설정이 직접 전달되면 사용, 아니면 GameState에서 읽음
   260→	FRoomSettings Settings;
   261→	if (InSettings)
   262→	{
   263→		Settings = *InSettings;
   264→	}
   265→	else if (CachedGameState)
   266→	{
   267→		Settings = CachedGameState->GetRoomSettings();
   268→	}
   269→	else
   270→	{
   271→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - CachedGameState is NULL"));
   272→		return;
   273→	}
   274→
   275→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - Updating with: RoomName='%s', GameMode='%s', MapName='%s'"),
   276→		*Settings.RoomName, *Settings.GameMode, *Settings.MapName);
   277→
   278→	// 방 이름 표시
   279→	if (RoomNameText)
   280→	{
   281→		RoomNameText->SetText(FText::FromString(Settings.RoomName));
   282→	}
   283→
   284→	// 게임 모드 표시
   285→	if (GameModeText)
   286→	{
   287→		GameModeText->SetText(FText::FromString(Settings.GameMode));
   288→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameModeText set to '%s'"), *Settings.GameMode);
   289→	}
   290→
   291→	// 맵 이름 표시
   292→	if (MapText)
   293→	{
   294→		FString MapDisplayName = Settings.MapName;
   295→		// User_ 접두사 제거하여 표시
   296→		MapDisplayName.RemoveFromStart(TEXT("User_"));
   297→		MapText->SetText(FText::FromString(MapDisplayName));
   298→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: MapText set to '%s'"), *MapDisplayName);
   299→	}
   300→
   301→	// ⭐ 플레이어 수 표시 (실시간으로 가져오기)
   302→	if (PlayerCountText && CachedGameState)
   303→	{
   304→		int32 CurrentPlayers = CachedGameState->GetPlayerCount();
   305→		int32 MaxPlayers = Settings.MaxPlayers;
   306→
   307→		FString PlayerCountStr = FString::Printf(TEXT("%d / %d"), CurrentPlayers, MaxPlayers);
   308→		PlayerCountText->SetText(FText::FromString(PlayerCountStr));
   309→
   310→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerCountText set to '%s'"), *PlayerCountStr);
   311→	}
   312→
   313→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Room info updated successfully"));
   314→}
   315→
   316→void UWaitingRoomHUDWidget::UpdatePlayerList()
   317→{
   318→	if (!CachedGameState || !PlayerListContainer)
   319→	{
   320→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdatePlayerList - GameState or Container is NULL"));
   321→		return;
   322→	}
   323→
   324→	// 기존 목록 제거
   325→	PlayerListContainer->ClearChildren();
   326→	PlayerButtonToIDMap.Empty();
   327→
   328→	// 플레이어 목록 가져오기 & 캐시
   329→	CachedPlayerDisplayList = CachedGameState->GetPlayerList();
   330→
   331→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Updating player list - %d players"), CachedPlayerDisplayList.Num());
   332→
   333→	// 버튼으로 표시 (클릭 시 프로필 팝업)
   334→	for (const FPlayerDisplayInfo& Info : CachedPlayerDisplayList)
   335→	{
   336→		UButton* PlayerButton = NewObject<UButton>(this);
   337→		if (!PlayerButton)
   338→		{
   339→			continue;
   340→		}
   341→
   342→		// 버튼 안에 텍스트 추가
   343→		UTextBlock* PlayerText = NewObject<UTextBlock>(this);
   344→		if (PlayerText)
   345→		{
   346→			FString DisplayText = Info.PlayerName;
   347→
   348→			if (Info.bIsHost)
   349→			{
   350→				DisplayText = FString::Printf(TEXT("[Host] %s"), *DisplayText);
   351→			}
   352→
   353→			if (Info.bIsReady)
   354→			{
   355→				DisplayText += TEXT(" (Ready)");
   356→			}
   357→
   358→			PlayerText->SetText(FText::FromString(DisplayText));
   359→			PlayerButton->AddChild(PlayerText);
   360→		}
   361→
   362→		// 버튼 → PlayerID 매핑 저장
   363→		PlayerButtonToIDMap.Add(PlayerButton, Info.PlayerID);
   364→
   365→		// 모든 버튼에 공통 핸들러 바인딩
   366→		PlayerButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnAnyPlayerButtonClicked);
   367→
   368→		PlayerListContainer->AddChild(PlayerButton);
   369→
   370→		UE_LOG(LogWjWorld, Warning, TEXT("  - %s (ID: %d)"), *Info.PlayerName, Info.PlayerID);
   371→	}
   372→}
   373→
   374→void UWaitingRoomHUDWidget::OnAnyPlayerButtonClicked()
   375→{
   376→	if (!PlayerListContainer)
   377→	{
   378→		return;
   379→	}
   380→
   381→	// 클릭된 버튼 찾기 (IsHovered + HasMouseCapture 조합으로 더 안정적으로 판별)
   382→	for (const auto& Pair : PlayerButtonToIDMap)
   383→	{
   384→		UButton* Btn = Pair.Key;
   385→		if (Btn && (Btn->IsHovered() || Btn->HasMouseCapture()))
