   396→void UWaitingRoomHUDWidget::ShowPlayerProfile(int32 PlayerID)
   397→{
   398→	if (!CachedGameState)
   399→	{
   400→		return;
   401→	}
   402→
   403→	// PlayerID로 PlayerState 검색
   404→	APlayerState* TargetPS = nullptr;
   405→	for (APlayerState* PS : CachedGameState->PlayerArray)
   406→	{
   407→		if (PS && PS->GetPlayerId() == PlayerID)
   408→		{
   409→			TargetPS = PS;
   410→			break;
   411→		}
   412→	}
   413→
   414→	if (!TargetPS)
   415→	{
   416→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: PlayerState not found for ID %d"), PlayerID);
   417→		return;
   418→	}
   419→
   420→	// 프로필 위젯 생성
   421→	if (!ProfileWidgetClass)
   422→	{
   423→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: ProfileWidgetClass is not set"));
   424→		return;
   425→	}
   426→
   427→	if (!ProfileWidgetInstance)
   428→	{
   429→		ProfileWidgetInstance = CreateWidget<UPlayerProfileWidget>(GetOwningPlayer(), ProfileWidgetClass);
   430→		if (ProfileWidgetInstance)
   431→		{
   432→			ProfileWidgetInstance->AddToViewport(100);
   433→		}
   434→	}
   435→
   436→	if (!ProfileWidgetInstance)
   437→	{
   438→		return;
   439→	}
   440→
   441→	// 자기 자신인지 확인
   442→	APlayerController* LocalPC = GetOwningPlayer();
   443→	if (LocalPC && LocalPC->PlayerState && LocalPC->PlayerState->GetPlayerId() == PlayerID)
   444→	{
   445→		// 자기 자신 → ShowLocalProfile
   446→		ProfileWidgetInstance->ShowLocalProfile();
   447→	}
   448→	else
   449→	{
   450→		// 타 플레이어
   451→		AWjWorldPlayerStateBase* BasePS = Cast<AWjWorldPlayerStateBase>(TargetPS);
   452→		FUniqueNetIdRepl UniqueId = TargetPS->GetUniqueId();
   453→		FText PlayerName = FText::FromString(TargetPS->GetPlayerName());
   454→		FCosmeticLoadout Loadout;
   455→		if (BasePS)
   456→		{
   457→			Loadout = BasePS->GetCosmeticLoadout();
   458→		}
   459→
   460→		ProfileWidgetInstance->ShowPlayerProfile(UniqueId, PlayerName, Loadout);
   461→	}
   462→
   463→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: ShowPlayerProfile for ID %d"), PlayerID);
   464→}
