   532→void UWaitingRoomHUDWidget::InitializeHostSettingsPanel()
   533→{
   534→	if (!GameModeComboBox || !MapComboBox)
   535→	{
   536→		return;
   537→	}
   538→
   539→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   540→	if (!DevSettings || DevSettings->MinigameCatalog.IsNull())
   541→	{
   542→		return;
   543→	}
   544→
   545→	UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   546→	if (!Catalog)
   547→	{
   548→		return;
   549→	}
   550→
   551→	GameModeComboBox->ClearOptions();
   552→	for (const FWjWorldMinigameDefinition& Def : Catalog->Minigames)
   553→	{
   554→		GameModeComboBox->AddOption(Def.GameModeId.ToString());
   555→	}
   556→
   557→	if (CachedGameState)
   558→	{
   559→		const FRoomSettings& Settings = CachedGameState->GetRoomSettings();
   560→		GameModeComboBox->SetSelectedOption(Settings.GameMode);
   561→		UpdateMapComboBoxForGameMode(Settings.GameMode);
   562→
   563→		if (!Settings.MapName.IsEmpty())
   564→		{
   565→			for (const auto& Pair : MapOptionDisplayToValue)
   566→			{
   567→				if (Pair.Value == Settings.MapName)
   568→				{
   569→					MapComboBox->SetSelectedOption(Pair.Key);
   570→					break;
   571→				}
   572→			}
   573→		}
   574→	}
   575→
   576→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Host settings panel initialized"));
   577→}
