   624→void UWaitingRoomHUDWidget::UpdateMapComboBoxForGameMode(const FString& GameModeId)
   625→{
   626→	if (!MapComboBox)
   627→	{
   628→		return;
   629→	}
   630→
   631→	MapComboBox->ClearOptions();
   632→	MapOptionDisplayToValue.Empty();
   633→
   634→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   635→	if (!DevSettings || DevSettings->MinigameCatalog.IsNull())
   636→	{
   637→		return;
   638→	}
   639→
   640→	UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   641→	if (!Catalog)
   642→	{
   643→		return;
   644→	}
   645→
   646→	const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*GameModeId));
   647→	if (Def)
   648→	{
   649→		for (const FWjWorldMinigameMapOption& Option : Def->MapOptions)
   650→		{
   651→			FString DisplayName = Option.DisplayName.ToString();
   652→			FString OptionValue = Option.OptionValue;
   653→
   654→			MapComboBox->AddOption(DisplayName);
   655→			MapOptionDisplayToValue.Add(DisplayName, OptionValue);
   656→		}
   657→	}
   658→
   659→	// ApproachingWall인 경우 유저 레이아웃도 추가
   660→	if (GameModeId == TEXT("ApproachingWall"))
   661→	{
   662→		if (!DevSettings->WallDescriptionAsset.IsNull())
   663→		{
   664→			UWjWorldWallDescriptionDataAsset* WallAsset = DevSettings->WallDescriptionAsset.LoadSynchronous();
   665→			if (WallAsset)
   666→			{
   667→				TArray<FWjWorldWallDescription> UserLayouts;
   668→				WallAsset->ScanUserWallLayouts(UserLayouts);
   669→
   670→				for (const FWjWorldWallDescription& Layout : UserLayouts)
   671→				{
   672→					FString DisplayName = Layout.WallName;
   673→					DisplayName.RemoveFromStart(TEXT("User_"));
   674→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   675→
   676→					MapComboBox->AddOption(DisplayStr);
   677→					MapOptionDisplayToValue.Add(DisplayStr, Layout.WallName);
   678→				}
   679→
   680→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d AW user layouts"), UserLayouts.Num());
   681→			}
   682→		}
   683→	}
   684→
   685→	// JumpMap인 경우 유저 레이아웃도 추가
   686→	if (GameModeId == TEXT("JumpMap"))
   687→	{
   688→		if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
   689→		{
   690→			UJumpMapLayoutDataAsset* LayoutAsset = DevSettings->JumpMapLayoutDataAsset.LoadSynchronous();
   691→			if (LayoutAsset)
   692→			{
   693→				TArray<FJumpMapLayout> UserLayouts;
   694→				LayoutAsset->ScanUserJumpMapLayouts(UserLayouts);
   695→
   696→				for (const FJumpMapLayout& Layout : UserLayouts)
   697→				{
   698→					FString DisplayName = Layout.LayoutName;
   699→					DisplayName.RemoveFromStart(TEXT("User_"));
   700→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   701→
   702→					MapComboBox->AddOption(DisplayStr);
   703→					MapOptionDisplayToValue.Add(DisplayStr, Layout.LayoutName);
   704→				}
   705→
   706→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d JumpMap user layouts"), UserLayouts.Num());
   707→			}
   708→		}
   709→	}
   710→
   711→	if (MapComboBox->GetOptionCount() > 0)
   712→	{
   713→		MapComboBox->SetSelectedIndex(0);
   714→	}
   715→
   716→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Map options updated for GameMode '%s' - %d options"),
   717→		*GameModeId, MapComboBox->GetOptionCount());
   718→}
