   731→void UWaitingRoomHUDWidget::OnApplySettingsClicked()
   732→{
   733→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked START ==="));
   734→
   735→	if (!CachedGameState)
   736→	{
   737→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: CachedGameState is NULL!"));
   738→		return;
   739→	}
   740→	if (!GameModeComboBox)
   741→	{
   742→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: GameModeComboBox is NULL!"));
   743→		return;
   744→	}
   745→	if (!MapComboBox)
   746→	{
   747→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: MapComboBox is NULL!"));
   748→		return;
   749→	}
   750→
   751→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   752→	if (!GameInstance || !GameInstance->GetSessionManager() || !GameInstance->GetSessionManager()->IsHost())
   753→	{
   754→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Only host can change settings (IsHost=%d)"),
   755→			GameInstance && GameInstance->GetSessionManager() ? GameInstance->GetSessionManager()->IsHost() : false);
   756→		return;
   757→	}
   758→
   759→	FRoomSettings OldSettings = CachedGameState->GetRoomSettings();
   760→	FRoomSettings NewSettings = OldSettings;
   761→
   762→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   763→	NewSettings.GameMode = SelectedGameMode;
   764→
   765→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   766→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   767→	{
   768→		NewSettings.MapName = *MapValue;
   769→	}
   770→	else
   771→	{
   772→		NewSettings.MapName = SelectedMapDisplay;
   773→	}
   774→
   775→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Applying settings change:"));
   776→	UE_LOG(LogWjWorld, Warning, TEXT("  GameMode: '%s' -> '%s'"), *OldSettings.GameMode, *NewSettings.GameMode);
   777→	UE_LOG(LogWjWorld, Warning, TEXT("  MapName: '%s' -> '%s'"), *OldSettings.MapName, *NewSettings.MapName);
   778→
   779→	CachedGameState->UpdateRoomSettings(NewSettings);
   780→
   781→	// ⭐ 호스트 로컬에서 Display Text 직접 업데이트 (델리게이트 타이밍 안전장치)
   782→	UpdateRoomInfo(&NewSettings);
   783→
   784→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked END ==="));
   785→}
