   787→void UWaitingRoomHUDWidget::ApplyCurrentUISettings()
   788→{
   789→	// 호스트가 아니면 무시
   790→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   791→	if (!GameInstance || !GameInstance->GetSessionManager() || !GameInstance->GetSessionManager()->IsHost())
   792→	{
   793→		return;
   794→	}
   795→
   796→	// 필요한 컴포넌트가 없으면 무시
   797→	if (!CachedGameState || !GameModeComboBox || !MapComboBox)
   798→	{
   799→		return;
   800→	}
   801→
   802→	FRoomSettings NewSettings = CachedGameState->GetRoomSettings();
   803→
   804→	// 현재 UI에서 선택된 게임 모드
   805→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   806→	if (!SelectedGameMode.IsEmpty())
   807→	{
   808→		NewSettings.GameMode = SelectedGameMode;
   809→	}
   810→
   811→	// 현재 UI에서 선택된 맵
   812→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   813→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   814→	{
   815→		NewSettings.MapName = *MapValue;
   816→	}
   817→	else if (!SelectedMapDisplay.IsEmpty())
   818→	{
   819→		NewSettings.MapName = SelectedMapDisplay;
   820→	}
   821→
   822→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Auto-applying UI settings before game start - GameMode: '%s', Map: '%s'"),
   823→		*NewSettings.GameMode, *NewSettings.MapName);
   824→
   825→	CachedGameState->UpdateRoomSettings(NewSettings);
   826→}
