   105→void UWjWorldGameRuleBase::OnGameEnd()
   106→{
   107→	if (!HasAuthority()) return;
   108→
   109→	UWorld* World = GetWorld();
   110→	if (World)
   111→	{
   112→		// 세션 종료 (InProgress → Ended) - WaitingRoom 복귀 후 다시 StartSession 가능하게
   113→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(World->GetGameInstance()))
   114→		{
   115→			GI->EndGame();
   116→		}
   117→
   118→		// ServerTravel URL 미리 계산 (타이머 콜백에서 this 접근 문제 방지)
   119→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   120→		FString TravelURL = Settings->GetWaitingRoomServerTravelURL();
   121→
   122→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase::OnGameEnd - Will travel to: %s in %f seconds"), *TravelURL, SecondsForGotoWaitingRoom);
   123→
   124→		// Lobby 맵을 사용하되 GameMode는 WaitingRoom으로 오버라이드
   125→		// World를 WeakPtr로 캡처하여 타이머 콜백에서 안전하게 접근
   126→		TWeakObjectPtr<UWorld> WeakWorld = World;
   127→		World->GetTimerManager().SetTimer(GotoWaitingRoomHandle, FTimerDelegate::CreateLambda([WeakWorld, TravelURL]() {
   128→			if (UWorld* ValidWorld = WeakWorld.Get())
   129→			{
   130→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase - Executing ServerTravel to: %s"), *TravelURL);
   131→				ValidWorld->ServerTravel(TravelURL);
   132→			}
   133→			else
   134→			{
   135→				UE_LOG(LogWjWorld, Error, TEXT("GameRuleBase - ServerTravel failed: World is invalid"));
   136→			}
   137→		}), SecondsForGotoWaitingRoom, false);
   138→
   139→		ChangeGamePhase(EGamePhase::Finished);
   140→	}
   141→
   142→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Ended"));
   143→}
