   109→		break;
   110→	case EGamePhase::Playing:
   111→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Started"));
   112→		break;
   113→	case EGamePhase::Finished:
   114→		// 결과 표시는 OnRep_GameResult에서 처리
   115→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Finished"));
   116→		break;
   117→	}
   118→
   119→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Phase changed to %d"), static_cast<int32>(CurrentPhase));
   120→}
