   122→void AWjWorldGameStatePlay::OnRep_IsGameStartCountDownReady()
   123→{
   124→	if (bIsGameStartCountDownReady)
   125→	{
   126→		UWorld* World = GetWorld();
   127→		if (!World) return;
   128→
   129→		APlayerController* PC = World->GetFirstPlayerController();
   130→		if (!PC) return;
   131→
   132→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   133→		if (!HUD) return;
   134→
   135→		// 늦게 참여한 클라이언트를 위해 남은 시간 계산
   136→		float RemainingTime = StartCountDownTime;
   137→		if (CountdownStartServerTime > 0.0)
   138→		{
   139→			double CurrentServerTime = GetServerWorldTimeSeconds();
   140→			double Elapsed = CurrentServerTime - CountdownStartServerTime;
   141→			RemainingTime = FMath::Max(0.0f, StartCountDownTime - static_cast<float>(Elapsed));
   142→		}
   143→
   144→		HUD->StartGameStartCountDown(RemainingTime);
   145→
   146→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Start Countdown Ready - %f seconds (original: %f)"), RemainingTime, StartCountDownTime);
   147→	}
   148→}
