   236→	const TArray<FMinigameStatDescriptor>& Descriptors = GetAllMinigameDescriptors();
   237→	for (const FMinigameStatDescriptor& Desc : Descriptors)
   238→	{
   239→		for (const FMinigameStatEntry& Entry : Desc.Stats)
   240→		{
   241→			int32 Value = 0;
   242→			if (GConfig->GetInt(*StatsConfigSection, *Entry.StatName.ToString(), Value, GGameIni))
   243→			{
   244→				LocalStats.Add(Entry.StatName, Value);
   245→			}
   246→			else
   247→			{
   248→				LocalStats.Add(Entry.StatName, 0);
   249→			}
