    19→void UWjWorldGameRuleApproachingWall::Initialize(AWjWorldGameModePlay* InGameMode)
    20→{
    21→	Super::Initialize(InGameMode);
    22→
    23→	// DeveloperSettings에서 WallDescriptionAsset 로드
    24→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    25→	TSoftObjectPtr<UWjWorldWallDescriptionDataAsset> WallDescAsset;
    26→	if (Settings && !Settings->WallDescriptionAsset.IsNull())
    27→	{
    28→		WallDescAsset = Settings->WallDescriptionAsset;
    29→	}
    30→
    31→	BrickSpawner = UWjWorldBrickSpawner::CreateBrickSpawner(this, WallDescAsset);
    32→	if (!BrickSpawner)
    33→	{
    34→		UE_LOG(LogWjWorld, Error, TEXT("Failed to create BrickSpawner in GameRuleApporachingWall"));
    35→	}
    36→
    37→	WallManager = UWjWorldWallManager::CreateWallManager(this);
    38→	if (!WallManager)
    39→	{
    40→		UE_LOG(LogWjWorld, Error, TEXT("Failed to create WallManager in GameRuleApporachingWall"));
