   248→void UWjWorldGameRuleJumpMap::OnGameEnd()
   249→{
   250→	if (!HasAuthority()) return;
   251→
   252→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   253→	if (GameState)
   254→	{
   255→		// 승자 결정: 가장 빠른 완주 시간
   256→		if (!WinnerPlayer.IsValid())
   257→		{
   258→			float BestTime = MAX_FLT;
   259→			for (const auto& WeakPS : AllPlayers)
   260→			{
   261→				if (!WeakPS.IsValid()) continue;
   262→				AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   263→				UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   264→				if (PlayerData && PlayerData->HasFinished() && PlayerData->GetFinishTime() < BestTime)
   265→				{
   266→					BestTime = PlayerData->GetFinishTime();
   267→					WinnerPlayer = PS;
   268→				}
   269→			}
   270→		}
   271→
   272→		if (WinnerPlayer.IsValid())
   273→		{
   274→			GameState->SetGameResult(WinnerPlayer->GetPlayerName(), true);
   275→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Winner: %s"), *WinnerPlayer->GetPlayerName());
   276→		}
   277→		else
   278→		{
   279→			GameState->SetGameResult(TEXT(""), false);
   280→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: No winner (time expired)"));
   281→		}
   282→	}
   283→
   284→	// 스폰된 게임플레이 액터 정리
   285→	for (const auto& WeakActor : SpawnedGameplayActors)
   286→	{
   287→		if (WeakActor.IsValid())
   288→		{
   289→			WeakActor->Destroy();
   290→		}
   291→	}
   292→	SpawnedGameplayActors.Empty();
   293→
   294→	Super::OnGameEnd();
   295→}
