   205→	if (PC->PlayerState)
   206→	{
   207→		LocalPlayerName = PC->PlayerState->GetPlayerName();
   208→	}
   209→
   210→	FString ResultText;
   211→	if (bGameHasWinner)
   212→	{
   213→		if (LocalPlayerName == WinnerPlayerName)
   214→		{
   215→			ResultText = TEXT("Victory!");
   216→		}
   217→		else
   218→		{
   219→			ResultText = FString::Printf(TEXT("%s Wins!"), *WinnerPlayerName);
   220→		}
   221→	}
   222→	else
   223→	{
   224→		ResultText = TEXT("Draw!");
   225→	}
   226→
   227→	HUD->ShowGameResultText(ResultText, 5.0f);
   228→
   229→	// 스탯 기록 (각 클라이언트가 자신의 스탯만 기록)
