   238→		{
   239→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Wins"), *NS)));
   240→		}
   241→		else
   242→		{
   243→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Losses"), *NS)));
