	int32 AlivePlayerCount = 0;
	int32 TotalPlayerCount = 0;
	bool bIsGameStarted = false;
	bool bGameOverConditionMet = false;

	// 라운드
	int32 CurrentRound = 0;
	bool bIsRoundActive = false;
	bool bIsResettingRound = false;

	/** 탈락 순서 기록 (역순으로 점수 부여) */
