    51→void AWjWorldGameStatePlay::GameStartWithCountdown(float CountdownTime)
    52→{
    53→	bIsGameStartCountDownReady = true;
    54→	StartCountDownTime = CountdownTime;
    55→
    56→	// 서버 시간 기록 (늦게 참여하는 클라이언트가 남은 시간 계산 가능)
    57→	if (HasAuthority())
    58→	{
    59→		CountdownStartServerTime = GetServerWorldTimeSeconds();
    60→	}
    61→
    62→	if(HasAuthority())
    63→	{
    64→		OnRep_IsGameStartCountDownReady();
    65→	}
    66→}
    67→
    68→void AWjWorldGameStatePlay::GameEndWithCountdown(float CountdownTime)
    69→{
    70→	bIsGameEndCountDownReady = true;
    71→	EndCountDownTime = CountdownTime;
    72→
    73→	if (HasAuthority())
    74→	{
    75→		OnRep_IsGameEndCountDownReady();
    76→	}
    77→}
    78→
    79→void AWjWorldGameStatePlay::SetGamePhase(EGamePhase NewPhase)
    80→{
    81→	CurrentPhase = NewPhase;
    82→	if (HasAuthority())
    83→	{
    84→		OnRep_GamePhase();
    85→	}
    86→}
    87→
    88→UWjWorldGameDataComponent* AWjWorldGameStatePlay::AddGameDataComponent(TSubclassOf<UWjWorldGameDataComponent> InDataComponentClass)
    89→{
    90→	if (InDataComponentClass)
    91→	{
    92→		GameDataComponent = NewObject<UWjWorldGameDataComponent>(this, InDataComponentClass);
    93→		AddInstanceComponent(GameDataComponent);
    94→		GameDataComponent->RegisterComponent();
    95→		GameDataComponent->SetIsReplicated(true);
    96→
    97→		return GameDataComponent;
    98→	}
    99→
   100→	return nullptr;
   101→}
   102→
   103→void AWjWorldGameStatePlay::OnRep_GamePhase()
   104→{
   105→	switch (CurrentPhase)
   106→	{
   107→	case EGamePhase::Ready:
   108→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Ready"));
   109→		break;
   110→	case EGamePhase::Playing:
   111→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Started"));
   112→		break;
   113→	case EGamePhase::Finished:
   114→		// 결과 표시는 OnRep_GameResult에서 처리
   115→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Finished"));
   116→		break;
   117→	}
   118→
   119→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Phase changed to %d"), static_cast<int32>(CurrentPhase));
   120→}
   121→
   122→void AWjWorldGameStatePlay::OnRep_IsGameStartCountDownReady()
   123→{
   124→	if (bIsGameStartCountDownReady)
   125→	{
   126→		UWorld* World = GetWorld();
   127→		if (!World) return;
   128→
   129→		APlayerController* PC = World->GetFirstPlayerController();
   130→		if (!PC) return;
   131→
   132→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   133→		if (!HUD) return;
   134→
   135→		// 늦게 참여한 클라이언트를 위해 남은 시간 계산
   136→		float RemainingTime = StartCountDownTime;
   137→		if (CountdownStartServerTime > 0.0)
   138→		{
   139→			double CurrentServerTime = GetServerWorldTimeSeconds();
   140→			double Elapsed = CurrentServerTime - CountdownStartServerTime;
   141→			RemainingTime = FMath::Max(0.0f, StartCountDownTime - static_cast<float>(Elapsed));
   142→		}
   143→
   144→		HUD->StartGameStartCountDown(RemainingTime);
   145→
   146→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Start Countdown Ready - %f seconds (original: %f)"), RemainingTime, StartCountDownTime);
   147→	}
   148→}
   149→
   150→void AWjWorldGameStatePlay::OnRep_IsGameEndCountDownReady()
   151→{
   152→	if (bIsGameEndCountDownReady)
   153→	{
   154→		UWorld* World = GetWorld();
   155→		if (!World) return;
   156→
   157→		APlayerController* PC = World->GetFirstPlayerController();
   158→		if (!PC) return;
   159→
   160→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   161→		if (!HUD) return;
   162→
   163→		HUD->StartGameStartCountDown(EndCountDownTime);
   164→
   165→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game End Countdown Ready - %f seconds"), EndCountDownTime);
   166→	}
   167→}
   168→
   169→void AWjWorldGameStatePlay::SetGameResult(const FString& WinnerName, bool bHasWinner)
   170→{
   171→	WinnerPlayerName = WinnerName;
   172→	bGameHasWinner = bHasWinner;
   173→	bGameResultReady = true;
   174→
   175→	if (HasAuthority())
   176→	{
   177→		OnRep_GameResult();
   178→	}
   179→}
   180→
   181→void AWjWorldGameStatePlay::SetGameRuleClass(TSubclassOf<UWjWorldGameRuleBase> InGameRuleClass)
   182→{
   183→	GameRuleClass = InGameRuleClass;
   184→
   185→	if (HasAuthority())
   186→	{
   187→		OnRep_GameRuleClass();
   188→	}
   189→}
   190→
   191→void AWjWorldGameStatePlay::OnRep_GameResult()
   192→{
   193→	if (!bGameResultReady) return;
   194→
   195→	UWorld* World = GetWorld();
   196→	if (!World) return;
   197→
   198→	APlayerController* PC = World->GetFirstPlayerController();
   199→	if (!PC) return;
   200→
   201→	AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   202→	if (!HUD) return;
   203→
   204→	FString LocalPlayerName;
   205→	if (PC->PlayerState)
   206→	{
   207→		LocalPlayerName = PC->PlayerState->GetPlayerName();
   208→	}
   209→
   210→	FString ResultText;
   211→	if (bGameHasWinner)
   212→	{
   213→		if (LocalPlayerName == WinnerPlayerName)
   214→		{
   215→			ResultText = TEXT("Victory!");
   216→		}
   217→		else
   218→		{
   219→			ResultText = FString::Printf(TEXT("%s Wins!"), *WinnerPlayerName);
   220→		}
   221→	}
   222→	else
   223→	{
   224→		ResultText = TEXT("Draw!");
   225→	}
   226→
   227→	HUD->ShowGameResultText(ResultText, 5.0f);
   228→
   229→	// 스탯 기록 (각 클라이언트가 자신의 스탯만 기록)
   230→	// StatNamespace 기반 동적 스탯 키 생성
   231→	UWjWorldStatsSubsystem* Stats = GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   232→	if (Stats && PC->PlayerState && !StatNamespace.IsNone())
   233→	{
   234→		FString NS = StatNamespace.ToString();
   235→		Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_GamesPlayed"), *NS)));
   236→
   237→		if (bGameHasWinner && WinnerPlayerName == LocalPlayerName)
   238→		{
   239→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Wins"), *NS)));
   240→		}
   241→		else
   242→		{
   243→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Losses"), *NS)));
   244→		}
   245→
   246→		Stats->StoreStats();
   247→	}
   248→
   249→	// 재화 보상 지급 (각 클라이언트가 자신의 보상 요청)
   250→	UWjWorldCurrencySubsystem* CurrencySub = GetGameInstance()->GetSubsystem<UWjWorldCurrencySubsystem>();
   251→	if (CurrencySub && PC->PlayerState)
   252→	{
   253→		bool bIsLocalPlayerWinner = bGameHasWinner && (WinnerPlayerName == LocalPlayerName);
   254→		CurrencySub->TriggerMatchReward(bIsLocalPlayerWinner);
   255→	}
   256→
   257→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Result - %s"), *ResultText);
   258→}
   259→
   260→void AWjWorldGameStatePlay::OnRep_GameRuleClass()
   261→{
   262→	UWorld* World = GetWorld();
   263→	if (!World) return;
   264→
   265→	APlayerController* PC = World->GetFirstPlayerController();
   266→	if (!PC) return;
   267→
   268→	AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   269→	if (!HUD) return;
   270→
   271→	HUD->ShowGameRuleHUDWidget(GameRuleClass);
   272→}
   273→
   274→void AWjWorldGameStatePlay::SetAllowedAbilityTags(const FGameplayTagContainer& InTags)
   275→{
   276→	AllowedAbilityTags = InTags;
   277→}
