    14→
    15→void UWjWorldGameRuleBase::Initialize(AWjWorldGameModePlay* InGameMode)
    16→{
    17→	if (InGameMode)
    18→	{
    19→		GameMode = InGameMode;
    20→	}
    21→
    22→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Initialized"));
    23→}
    24→
    25→void UWjWorldGameRuleBase::OnGameReady()
    26→{
    27→	if (!HasAuthority()) return;
    28→
    29→	// GameState는 InitGameState() (PreInitializeComponents) 이후에 생성되므로
    30→	// Initialize() 시점에는 없고, OnGameReady() (StartPlay) 시점에 사용 가능
    31→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
    32→	if (GameState && GameDataComponentClass)
    33→	{
    34→		GameState->AddGameDataComponent(GameDataComponentClass);
    35→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: GameDataComponent added to GameState"));
    36→	}
    37→
    38→	// MinigameCatalog에서 AllowedAbilityTags, StatNamespace 설정
    39→	if (GameState && GameMode.IsValid())
    40→	{
    41→		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    42→		if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
    43→		{
    44→			UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
    45→			FString CurrentGameModeId = GameMode->GetMapOption();
    46→			// GameModeId는 URL Options에서 직접 가져오기
    47→			const FWjWorldMinigameDefinition* Def = nullptr;
    48→			if (Catalog)
    49→			{
    50→				// GameModePlay의 InitGame에서 파싱된 GameModeId를 사용해야 하므로
    51→				// 카탈로그에서 현재 GameRule 클래스를 기준으로 찾기
    52→				for (const FWjWorldMinigameDefinition& MiniDef : Catalog->Minigames)
    53→				{
    54→					if (MiniDef.GameRuleClass == GetClass())
    55→					{
    56→						Def = &MiniDef;
    57→						break;
    58→					}
    59→				}
    60→			}
    61→
    62→			if (Def)
    63→			{
    64→				GameState->SetAllowedAbilityTags(Def->AllowedAbilityTags);
    65→				GameState->SetStatNamespace(Def->StatNamespace);
    66→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: AllowedAbilityTags set (%d tags), StatNamespace='%s'"),
    67→					Def->AllowedAbilityTags.Num(), *Def->StatNamespace.ToString());
    68→			}
    69→		}
    70→	}
    71→
    72→	UWorld* World = GetWorld();
    73→	if (World)
    74→	{
    75→		World->GetTimerManager().SetTimer(DelayStartHandle, FTimerDelegate::CreateLambda([this]() {
    76→			if (GameMode.IsValid())
    77→			{
    78→				GameMode->StartGame(SecondsForGameStartCount);
    79→			}
    80→			}), StartDelay, false);
    81→
    82→		ChangeGamePhase(EGamePhase::Ready);
    83→	}
    84→
    85→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Ready"));
    86→}
    87→
    88→void UWjWorldGameRuleBase::OnGameStart()
    89→{
    90→	if (!HasAuthority()) return;
    91→
    92→	ChangeGamePhase(EGamePhase::Playing);
    93→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Started"));
    94→}
    95→
    96→void UWjWorldGameRuleBase::OnGameEndPredict(float Seconds)
    97→{
    98→	if (!HasAuthority()) return;
    99→	if (GameMode.IsValid())
   100→	{
   101→		GameMode->EndGamePredict(Seconds);
   102→	}
   103→}
   104→
   105→void UWjWorldGameRuleBase::OnGameEnd()
   106→{
   107→	if (!HasAuthority()) return;
   108→
   109→	UWorld* World = GetWorld();
   110→	if (World)
   111→	{
   112→		// 세션 종료 (InProgress → Ended) - WaitingRoom 복귀 후 다시 StartSession 가능하게
   113→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(World->GetGameInstance()))
   114→		{
   115→			GI->EndGame();
   116→		}
   117→
   118→		// ServerTravel URL 미리 계산 (타이머 콜백에서 this 접근 문제 방지)
   119→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   120→		FString TravelURL = Settings->GetWaitingRoomServerTravelURL();
   121→
   122→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase::OnGameEnd - Will travel to: %s in %f seconds"), *TravelURL, SecondsForGotoWaitingRoom);
   123→
   124→		// Lobby 맵을 사용하되 GameMode는 WaitingRoom으로 오버라이드
   125→		// World를 WeakPtr로 캡처하여 타이머 콜백에서 안전하게 접근
   126→		TWeakObjectPtr<UWorld> WeakWorld = World;
   127→		World->GetTimerManager().SetTimer(GotoWaitingRoomHandle, FTimerDelegate::CreateLambda([WeakWorld, TravelURL]() {
   128→			if (UWorld* ValidWorld = WeakWorld.Get())
   129→			{
   130→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase - Executing ServerTravel to: %s"), *TravelURL);
   131→				ValidWorld->ServerTravel(TravelURL);
   132→			}
   133→			else
   134→			{
   135→				UE_LOG(LogWjWorld, Error, TEXT("GameRuleBase - ServerTravel failed: World is invalid"));
   136→			}
   137→		}), SecondsForGotoWaitingRoom, false);
   138→
   139→		ChangeGamePhase(EGamePhase::Finished);
   140→	}
   141→
   142→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Ended"));
   143→}
   144→
   145→void UWjWorldGameRuleBase::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   146→{
   147→	if (!HasAuthority()) return;
   148→	if (!Player) return;
   149→
   150→	if (PlayerDataComponentClass)
   151→	{
   152→		Player->AddGameDataComponent(PlayerDataComponentClass);
   153→	}
   154→
   155→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Player Joined - %s"), *Player->GetName());
   156→}
   157→
   158→void UWjWorldGameRuleBase::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   159→{
   160→	if (!HasAuthority()) return;
   161→}
   162→
   163→bool UWjWorldGameRuleBase::CheckWinCondition() const
   164→{
   165→	return false;
   166→}
   167→
   168→AWjWorldPlayerStatePlay* UWjWorldGameRuleBase::GetWinner() const
   169→{
   170→	return nullptr;
   171→}
   172→
   173→void UWjWorldGameRuleBase::TickGameRule(float DeltaTime)
   174→{
   175→	// 서브클래스에서 오버라이드
   176→}
   177→
   178→void UWjWorldGameRuleBase::BeginDestroy()
   179→{
   180→	Super::BeginDestroy();
   181→	
   182→	UWorld* World = GetWorld();
   183→	if (World)
   184→	{
   185→		World->GetTimerManager().ClearTimer(DelayStartHandle);
   186→		World->GetTimerManager().ClearTimer(GotoWaitingRoomHandle);
   187→	}
   188→}
   189→
   190→AWjWorldGameModePlay* UWjWorldGameRuleBase::GetGameModePlay() const
   191→{
   192→	UWorld* World = GetWorld();
   193→	if (World)
   194→	{
   195→		return World->GetAuthGameMode<AWjWorldGameModePlay>();
   196→	}
   197→	return nullptr;
   198→}
   199→
   200→AWjWorldGameStatePlay* UWjWorldGameRuleBase::GetGameStatePlay() const
   201→{
   202→	UWorld* World = GetWorld();
   203→	if (World)
   204→	{
   205→		return World->GetGameState<AWjWorldGameStatePlay>();
   206→	}
   207→	return nullptr;
   208→}
   209→
   210→void UWjWorldGameRuleBase::GameLevelUp(int32 NewLevel)
   211→{
   212→	if (!HasAuthority()) return;
   213→
   214→	AWjWorldGameModePlay* GameModePlay = GetGameModePlay();
   215→	if (GameModePlay)
   216→	{
   217→		GameModePlay->OnGameLevelUp(NewLevel);
   218→	}
   219→
   220→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Level Up to %d"), NewLevel);
   221→}
   222→
   223→void UWjWorldGameRuleBase::ChangeGamePhase(EGamePhase GamePhase)
   224→{
   225→	if (!HasAuthority()) return;
   226→
   227→	if (AWjWorldGameStatePlay* GameStatePlay = GetGameStatePlay())
   228→	{
   229→		GameStatePlay->SetGamePhase(GamePhase);
   230→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Phase changed to %d"), static_cast<int32>(GamePhase));
   231→	}
   232→}
