	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Start button enabled = %d (AllReady=%d, Count=%d, MinPlayers=%d)"),
		bCanStart, bAllReady, PlayerCount, MinPlayers);
}

