    21→	}
    22→	else
    23→	{
    24→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to create SessionManager"));
    25→	}
    26→
    27→	// NetworkFailure 핸들러 등록
    28→	if (GEngine)
    29→	{
    30→		NetworkFailureHandle = GEngine->OnNetworkFailure().AddUObject(
    31→			this, &UWjWorldGameInstance::HandleNetworkFailure);
    32→		TravelFailureHandle = GEngine->OnTravelFailure().AddUObject(
    33→			this, &UWjWorldGameInstance::HandleTravelFailure);
