    38→void UWjWorldGameInstance::Shutdown()
    39→{
    40→	// 타이머 정리
    41→	UWorld* World = GetWorld();
    42→	if (World)
    43→	{
    44→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
    45→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
    46→	}
    47→
    48→	// NetworkFailure / TravelFailure 핸들러 해제
    49→	if (GEngine)
    50→	{
    51→		GEngine->OnNetworkFailure().Remove(NetworkFailureHandle);
    52→		GEngine->OnTravelFailure().Remove(TravelFailureHandle);
    53→	}
    54→
    55→	// SessionManager 정리
    56→	if (SessionManager)
    57→	{
    58→		SessionManager->Shutdown();
    59→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: SessionManager shutdown"));
    60→	}
    61→
    62→	Super::Shutdown();
    63→}
