    22→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_SpawnBrickPreview());
    23→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_LiftBrickCarry());
    24→
    25→	// 쿨다운 설정
    26→	CooldownDuration = GrappleCooldownDuration;
    27→	CooldownTags.AddTag(WjWorldGameplayTag::Cooldown_Grapple());
    28→
    29→	// UI 메타데이터
    30→	AbilityName = NSLOCTEXT("Abilities", "Grapple", "그래플");
    31→}
    32→
    33→void UGA_Grapple::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    34→{
    35→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    36→
    37→	// EndAbility 호출용 캐시
    38→	CachedHandle = Handle;
    39→	CachedActorInfo = ActorInfo;
    40→	CachedActivationInfo = ActivationInfo;
    41→
    42→	ACharacter* Character = Cast<ACharacter>(ActorInfo->AvatarActor.Get());
    43→	if (!Character)
    44→	{
    45→		EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    46→		return;
    47→	}
    48→
    49→	APlayerController* PC = Cast<APlayerController>(Character->GetController());
    50→	if (!PC)
    51→	{
    52→		EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    53→		return;
    54→	}
    55→
    56→	// 카메라 방향으로 라인 트레이스
    57→	FVector CamLoc;
    58→	FRotator CamRot;
    59→	PC->GetPlayerViewPoint(CamLoc, CamRot);
    60→
    61→	FVector TraceEnd = CamLoc + CamRot.Vector() * GrappleRange;
    62→	FHitResult HitResult;
    63→	FCollisionQueryParams Params;
    64→	Params.AddIgnoredActor(Character);
    65→
    66→	if (GetWorld()->LineTraceSingleByChannel(HitResult, CamLoc, TraceEnd, ECC_Visibility, Params))
    67→	{
    68→		AJumpMapGrapplePointActor* GrapplePoint = Cast<AJumpMapGrapplePointActor>(HitResult.GetActor());
    69→		if (GrapplePoint)
    70→		{
    71→			if (!CommitAbility(Handle, ActorInfo, ActivationInfo))
    72→			{
    73→				EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    74→				return;
    75→			}
    76→
    77→			GrappleTargetLocation = GrapplePoint->GetActorLocation();
    78→			bIsPulling = true;
    79→
    80→			// 캐릭터를 타겟 방향으로 발사
    81→			FVector Direction = (GrappleTargetLocation - Character->GetActorLocation()).GetSafeNormal();
    82→			Character->LaunchCharacter(Direction * GrapplePullSpeed, true, true);
    83→
    84→			UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_Grapple: Pulling %s toward %s"),
    85→				*Character->GetName(), *GrappleTargetLocation.ToString());
    86→
    87→			// 도착 체크 타이머 (매 틱)
    88→			if (UWorld* World = GetWorld())
    89→			{
    90→				World->GetTimerManager().SetTimerForNextTick(FTimerDelegate::CreateUObject(this, &UGA_Grapple::CheckArrival));
    91→			}
    92→			return;
    93→		}
    94→	}
    95→
    96→	// 미스 → 쿨다운 없이 종료
    97→	EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
    98→}
    99→
   100→void UGA_Grapple::CheckArrival()
   101→{
   102→	if (!bIsPulling)
   103→	{
   104→		return;
   105→	}
   106→
   107→	if (!CachedActorInfo || !CachedActorInfo->AvatarActor.IsValid())
   108→	{
   109→		bIsPulling = false;
   110→		EndAbility(CachedHandle, CachedActorInfo, CachedActivationInfo, true, true);
   111→		return;
   112→	}
   113→
   114→	ACharacter* Character = Cast<ACharacter>(CachedActorInfo->AvatarActor.Get());
   115→	if (!Character)
   116→	{
   117→		bIsPulling = false;
   118→		EndAbility(CachedHandle, CachedActorInfo, CachedActivationInfo, true, true);
   119→		return;
   120→	}
   121→
   122→	float Distance = FVector::Dist(Character->GetActorLocation(), GrappleTargetLocation);
   123→	if (Distance <= ArrivalThreshold)
   124→	{
   125→		bIsPulling = false;
   126→		EndAbility(CachedHandle, CachedActorInfo, CachedActivationInfo, true, false);
   127→		return;
   128→	}
   129→
   130→	// 아직 이동 중 → 다음 틱에 다시 체크
   131→	if (UWorld* World = GetWorld())
   132→	{
   133→		World->GetTimerManager().SetTimerForNextTick(FTimerDelegate::CreateUObject(this, &UGA_Grapple::CheckArrival));
   134→	}
   135→}
