   195→void AWjWorldCharacterPlay::PossessedBy(AController* NewController)
   196→{
   197→	Super::PossessedBy(NewController);
   198→
   199→	APlayerState* WJPlayerState = GetPlayerState<AWjWorldPlayerStatePlay>();
   200→	IAbilitySystemInterface* AbilitySystemInterface = Cast<IAbilitySystemInterface>(WJPlayerState);
   201→	if (AbilitySystemInterface)
   202→	{
   203→		AbilitySystemComponent = Cast<UWjWorldAbilitySystemComponent>(AbilitySystemInterface->GetAbilitySystemComponent());
   204→		if (!ensureMsgf(AbilitySystemComponent.IsValid(), TEXT("AWjWorldCharacterPlay::PossessedBy - AbilitySystemComponent is invalid")))
   205→		{
   206→			return;
   207→		}
   208→		AbilitySystemComponent->InitAbilityActorInfo(WJPlayerState, this);
   209→		AbilitySystemComponent->SetOwnerActor(NewController);
   210→
   211→		// Confirm/Cancel InputID 설정
   212→		AbilitySystemComponent->GenericConfirmInputID = static_cast<int32>(EWjWorldAbilityInputID::Confirm);
   213→		AbilitySystemComponent->GenericCancelInputID = static_cast<int32>(EWjWorldAbilityInputID::Cancel);
   214→
   215→		FLoadSoftObjectPathAsyncDelegate SetupDataLoadDel;
   216→		SetupDataLoadDel.BindUObject(this, &ThisClass::OnSetupDataAssetLoaded);
   217→		SetupDataAsset.LoadAsync(SetupDataLoadDel);
   218→	}
   219→
   220→	// 코스메틱 로드아웃 설정 (서버에서)
   221→	if (HasAuthority())
   222→	{
   223→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>())
   224→		{
   225→			if (CosmeticComponent)
   226→			{
   227→				CosmeticComponent->SetCatalog(CosmeticSub->GetCatalog());
   228→			}
   229→
   230→			if (AWjWorldPlayerStatePlay* PS = GetPlayerState<AWjWorldPlayerStatePlay>())
   231→			{
   232→				// 리스폰 시 PlayerState에 이미 로드아웃이 있으면 덮어쓰지 않음
   233→				// (호스트의 로드아웃으로 다른 플레이어 로드아웃을 덮어쓰는 버그 방지)
   234→				if (PS->GetCosmeticLoadout().Entries.IsEmpty())
   235→				{
   236→					// 최초 스폰: 로컬 서브시스템에서 로드아웃 가져옴 (서버 자신의 캐릭터만 해당)
   237→					APlayerController* PC = Cast<APlayerController>(NewController);
   238→					if (PC && PC->IsLocalController())
   239→					{
   240→						PS->SetCosmeticLoadout(CosmeticSub->GetLoadout());
   241→					}
   242→				}
   243→				// 서버에서도 Pawn 설정 알림 (기존 로드아웃 적용)
   244→				PS->OnPawnSet(nullptr, this);
   245→			}
   246→		}
   247→	}
   248→}
