   417→void AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex_Implementation(int32 GridX, int32 GridY)
   418→{
   419→	UE_LOG(LogWjWorld, Log, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - GridIndex: (%d, %d)"), GridX, GridY);
   420→
   421→	UWorld* World = GetWorld();
   422→	if (!World)
   423→	{
   424→		return;
   425→	}
   426→
   427→	// 서버에서 WallDesc 가져오기
   428→	FWjWorldWallDescription ServerWallDesc;
   429→	AWjWorldGameModePlay* GameModePlay = World->GetAuthGameMode<AWjWorldGameModePlay>();
   430→	if (GameModePlay)
   431→	{
   432→		UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
   433→		if (GameRule)
   434→		{
   435→			ServerWallDesc = GameRule->GetWallDesc();
   436→		}
   437→	}
   438→
   439→	// WallDesc가 유효하지 않으면 실패
   440→	if (ServerWallDesc.BrickSize.IsZero() || ServerWallDesc.ColumnNum == 0)
   441→	{
   442→		UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - Invalid WallDesc"));
   443→		return;
   444→	}
   445→
   446→	// 그리드 범위 체크
   447→	if (GridX < 0 || GridX >= ServerWallDesc.ColumnNum ||
   448→		GridY < 0 || GridY >= ServerWallDesc.RowNum)
   449→	{
   450→		UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - Invalid GridIndex (%d, %d) for grid %dx%d"),
   451→			GridX, GridY, ServerWallDesc.ColumnNum, ServerWallDesc.RowNum);
   452→		return;
   453→	}
   454→
   455→	// 충전 소모 (ASC에서)
   456→	if (AbilitySystemComponent.IsValid())
   457→	{
   458→		const UGameplayEffect* CostGE = UGE_SpawnBrickChargeCost::StaticClass()->GetDefaultObject<UGameplayEffect>();
   459→		if (CostGE)
   460→		{
   461→			FGameplayEffectContextHandle ContextHandle = AbilitySystemComponent->MakeEffectContext();
   462→			FGameplayEffectSpec Spec(CostGE, ContextHandle, 1.f);
   463→			AbilitySystemComponent->ApplyGameplayEffectSpecToSelf(Spec);
   464→		}
   465→	}
   466→
   467→	FIntPoint SpawnIndexPoint(GridX, GridY);
   468→	FVector SpawnPosition = UWjWorldBrickSpawner::CalculateBrickPosition(
   469→		GridX,
   470→		GridY,
   471→		ServerWallDesc.ColumnNum,
   472→		ServerWallDesc.RowNum,
   473→		ServerWallDesc.CenterOffset,
   474→		ServerWallDesc.BrickSize
   475→	);
   476→
   477→	FWjWorldBrickProperties BrickProperties;
   478→	BrickProperties.BrickType = FMath::RandBool() ? EWjWorldBrickType::Moving : EWjWorldBrickType::Destructible;
   479→	BrickProperties.BrickMoveType = EWjWorldBrickMoveType::Standard;
   480→	BrickProperties.Size = ServerWallDesc.BrickSize;
   481→	BrickProperties.Color = BrickProperties.GetColorWithBrickType();
   482→	BrickProperties.SpawnedGridPosition = SpawnIndexPoint;
   483→	BrickProperties.CenterOffset = ServerWallDesc.CenterOffset;
   484→	BrickProperties.ColumnNum = ServerWallDesc.ColumnNum;
   485→	BrickProperties.RowNum = ServerWallDesc.RowNum;
   486→
   487→	// Destructible 벽돌은 DeveloperSettings에서 MaxHP 설정
   488→	if (BrickProperties.BrickType == EWjWorldBrickType::Destructible)
   489→	{
   490→		BrickProperties.MaxHP = GetDefault<UWjWorldDeveloperSettings>()->DestructibleBrickDefaultHP;
   491→	}
   492→
   493→	UWjWorldBrickSpawner::SpawnBrickActor(World, BrickProperties, GridX, GridY);
   494→
   495→	// GameplayCue 실행 (사운드/VFX)
   496→	if (AbilitySystemComponent.IsValid())
   497→	{
   498→		FGameplayCueParameters CueParams;
   499→		CueParams.Location = SpawnPosition;
   500→		AbilitySystemComponent->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Ability_SpawnBrick(), CueParams);
   501→	}
   502→}
   503→
   504→void AWjWorldCharacterPlay::ServerLiftBrickAtGridIndex_Implementation(int32 GridX, int32 GridY)
   505→{
   506→	UE_LOG(LogWjWorld, Log, TEXT("AWjWorldCharacterPlay::ServerLiftBrickAtGridIndex - GridIndex: (%d, %d)"), GridX, GridY);
   507→
   508→	UAbilitySystemComponent* ASC = GetAbilitySystemComponent();
   509→	if (!ASC) return;
   510→
   511→	// 활성 GA_LiftBrick 어빌리티 인스턴스 찾기
   512→	for (FGameplayAbilitySpec& Spec : ASC->GetActivatableAbilities())
   513→	{
   514→		UGA_LiftBrick* LiftBrickAbility = Cast<UGA_LiftBrick>(Spec.GetPrimaryInstance());
   515→		if (LiftBrickAbility && LiftBrickAbility->IsActive())
   516→		{
   517→			LiftBrickAbility->ServerHandleBrickPickup(GridX, GridY);
   518→			return;
   519→		}
   520→	}
   521→
   522→	UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerLiftBrickAtGridIndex - No active GA_LiftBrick found"));
   523→}
