    56→void UWjWorldGameplayAbilityBase::ApplyCooldown(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo) const
    57→{
    58→	if (CooldownDuration <= 0.f || CooldownTags.Num() == 0)
    59→	{
    60→		return;
