void USettingsWindow::ShowPopup()
{
    // Add to viewport with high Z-order (100+ for popup)
    AddToViewport(100);

    // Set input mode to UI-only
    APlayerController* PC = GetWorld()->GetFirstPlayerController();
    if (PC)
    {
